writeFileSync(modelPath, bytes);

const policy = { requireUVs: false, requireNormals: true, requireBaseColorTexture: false, maxTriangles: 45000, maxMaterials: 32, maxDimensionMeters: 2.1, minDimensionMeters: .02 };
const policyPath = resolve(outputDir, 'validation-policy.json');
