const sources = ['src/app/chef/diner-preview/character-kit.ts', 'src/app/chef/diner-preview/material-library.ts', 'scripts/dk-diner-source-loader.mjs', 'scripts/dk-export-character-proof.mjs'];
const sha256 = value => createHash('sha256').update(value).digest('hex');
